-- Preserve original check IDs and predicates; use the pinned shared terminal check.
with terminal_function as materialized(select (exists(select 1 from pg_catalog.pg_proc p
  where p.oid=pg_catalog.to_regprocedure('public.treasure_vault_terminal_status_v1()')
    and pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to((p.prosrc)::text,'UTF8')),'hex')='306b98528f553f9089d3b46c8541b30121c9cdf1c30a48a69034842982f22c87'
    and p.prokind='f' and p.prolang=(select l.oid from pg_catalog.pg_language l where l.lanname='sql')
    and p.provolatile='s' and p.prosecdef is false and p.proisstrict is false and p.proleakproof is false
    and p.proparallel='u' and p.procost=100 and p.prorows=1
    and p.pronargs=0 and p.pronargdefaults=0 and p.proretset is true
    and p.prorettype=pg_catalog.to_regtype('record')
    and p.proallargtypes=array[pg_catalog.to_regtype('boolean')::oid,pg_catalog.to_regtype('boolean')::oid]
    and p.proargmodes=array['t','t']::"char"[] and p.proargnames=array['recognized','passed']::text[]
    and p.proconfig=array['search_path=""']::text[] and p.proowner=pg_catalog.to_regrole('postgres')
    and (select count(*)=3
      and count(*) filter(where a.grantee=pg_catalog.to_regrole('postgres'))=1
      and count(*) filter(where a.grantee=pg_catalog.to_regrole('service_role'))=1
      and count(*) filter(where a.grantee=pg_catalog.to_regrole('supabase_read_only_user'))=1
      and bool_and((a.privilege_type='EXECUTE' and a.is_grantable is false
      and a.grantor=pg_catalog.to_regrole('postgres')
      and a.grantee in(pg_catalog.to_regrole('postgres'),pg_catalog.to_regrole('service_role'),pg_catalog.to_regrole('supabase_read_only_user'))) is true)
      from pg_catalog.aclexplode(coalesce(p.proacl,pg_catalog.acldefault('f',p.proowner))) a)
    and pg_catalog.has_function_privilege('postgres',p.oid,'EXECUTE')
    and pg_catalog.has_function_privilege('service_role',p.oid,'EXECUTE')
    and pg_catalog.has_function_privilege('supabase_read_only_user',p.oid,'EXECUTE'))) as valid),
terminal_status as materialized(select case when f.valid is true then
  coalesce((select pg_catalog.to_jsonb(s) from public.treasure_vault_terminal_status_v1() s),'{"recognized":true,"passed":false}'::jsonb)
  else '{"recognized":true,"passed":false}'::jsonb end as value from terminal_function f),
original_checks as(
with settings as(select $gifts${"blocks":[{"id":29513,"expected":{"id":29513,"cost":"","name":"Fervor","type":"feat","uuid":"1690381693754808","level":1,"access":"","rarity":"COMMON","actions":"ONE-ACTION","special":"","trigger":"","version":null,"frequency":"once per hour","operations":[],"availability":null,"requirements":"","prerequisites":[],"content_source_id":16},"metadata":{},"metadata_absent":["deprecated","unselectable","hidden"],"before":{"traits":[3460,3489,3479,1486,1448,1469,1432],"description":"**Gift Type** Minor\n\n**Aspect** emotion\n\nYou gain the emotional fervor benefits for your [relic's](link_trait_3460) [emotional state](link_feat_22493) for the next 3 rounds, but ignore the spell associated with the fervor. The feeling wears off quickly, so you experience no emotional fallout.","source":{"url":"https://2e.aonprd.com/Relics.aspx?ID=205","book":"Treasure Vault","page":"199"}},"after":{"traits":[3460,3489,3479,1486,1448,1432],"description":"**Gift Type** Minor\n\n**Aspect** emotion\n\nYou gain the emotional fervor benefits for your [relic's](link_trait_3460) [emotional state](link_feat_22493) for the next 3 rounds, but ignore the spell associated with the fervor. The feeling wears off quickly, so you experience no emotional fallout.","source":{"url":"https://2e.aonprd.com/Relics.aspx?ID=93","book":"Treasure Vault (Remastered)","page":"199"}}},{"id":29806,"expected":{"id":29806,"cost":"","name":"Sands of the Hourglass","type":"feat","uuid":"874046999605701","level":5,"access":"","rarity":"COMMON","actions":"TWO-ACTIONS","special":"","trigger":"","version":null,"frequency":"once per hour","operations":[],"availability":null,"requirements":"","prerequisites":["The relic is 5th level or higher"],"content_source_id":16},"metadata":{},"metadata_absent":["deprecated","unselectable","hidden"],"before":{"traits":[3460,3501,3479,1469,1432,1433],"description":"**Gift Type** Minor\n\n**Aspect** time\n\nYou target one creature within 30 feet, temporarily imposing the decrepitude of time on it. The target must attempt a Fortitude saving throw. The clumsy and enfeebled conditions last 1 minute.\n\n**Critical Success** The target is unaffected.\n\n**Success** The target becomes clumsy 1 and enfeebled 1.\n\n**Failure** The target becomes clumsy 2, enfeebled 2, and drained 1.\n\n**Critical Failure** The target becomes clumsy 3, enfeebled 3, and drained 2.","source":{"url":"https://2e.aonprd.com/Relics.aspx?ID=216","book":"Treasure Vault","page":"200"}},"after":{"traits":[3460,3501,3479,1432,1433],"description":"**Gift Type** Minor\n\n**Aspect** time\n\nYou target one creature within 30 feet, temporarily imposing the decrepitude of time on it. The target must attempt a Fortitude saving throw. The clumsy and enfeebled conditions last 1 minute.\n\n**Critical Success** The target is unaffected.\n\n**Success** The target becomes clumsy 1 and enfeebled 1.\n\n**Failure** The target becomes clumsy 2, enfeebled 2, and drained 1.\n\n**Critical Failure** The target becomes clumsy 3, enfeebled 3, and drained 2.","source":{"url":"https://2e.aonprd.com/Relics.aspx?ID=104","book":"Treasure Vault (Remastered)","page":"200"}}},{"id":29688,"expected":{"id":29688,"cost":"","name":"Intelligent Relic","type":"feat","uuid":"3638174940965762","level":1,"access":"","rarity":"COMMON","actions":null,"special":"","trigger":"","version":null,"frequency":"","operations":[],"availability":null,"requirements":"","prerequisites":[],"content_source_id":16},"metadata":{},"metadata_absent":["deprecated","unselectable","hidden"],"before":{"traits":[3460,3493,3479,1613],"description":"**Gift Type** Minor\n\n**Aspect** intelligent relic\n\nYour [relic](link_trait_3460) becomes an [intelligent](link_trait_1613) item. The [relic](link_trait_3460) possesses [precise sight](link_sense_20776) at a range of 30 feet and [imprecise hearing](link_sense_21081) at a range of 30 feet. It is trained in Perception, increasing its proficiency when you increase yours. Choose whether it can speak aloud or communicate with you [telepathically](link_physical-feature_28884). It knows languages fitting its backstory, usually from among those you know.\n\nThe [relic](link_trait_3460) is also trained in three skills, increasing one skill's proficiency each time the [relic](link_trait_3460) gains a new gift. Your [relic's](link_trait_3460) mental attribute modifiers begin at +3, +2, and +1, arranged as you choose. The [relic](link_trait_3460) is also trained in Will saves, and its proficiency increases as yours does. Each time you gain a new gift, increase one of the [relic's](link_trait_3460) mental modifiers scores by 2 or two by 1. The relic otherwise functions as normal for an [intelligent](link_trait_1613) item.\n\nIf you’re sanctified to [holy](link_trait_1630) or to [unholy](link_trait_1846), you can choose to have your relic sanctified in the same way.","source":{"url":"https://2e.aonprd.com/Relics.aspx?ID=221","book":"Treasure Vault","page":"200"}},"after":{"traits":[3460,3493,3479,1613],"description":"**Gift Type** Minor\n\n**Aspect** intelligent relic\n\nYour [relic](link_trait_3460) becomes an [intelligent](link_trait_1613) item. The [relic](link_trait_3460) possesses [precise sight](link_sense_20776) at a range of 30 feet and [imprecise hearing](link_sense_21081) at a range of 30 feet. It is trained in Perception, increasing its proficiency when you increase yours. Choose whether it can speak aloud or communicate with you [telepathically](link_physical-feature_28884). It knows languages fitting its backstory, usually from among those you know.\n\nThe [relic](link_trait_3460) is also trained in three skills, increasing one skill's proficiency each time the [relic](link_trait_3460) gains a new gift. Your [relic's](link_trait_3460) mental attribute modifiers begin at +3, +2, and +1, arranged as you choose. The [relic](link_trait_3460) is also trained in Will saves, and its proficiency increases as yours does. Each time you gain a new gift, increase one of the [relic's](link_trait_3460) mental attribute modifiers by 1. The [relic](link_trait_3460) otherwise functions as normal for an [intelligent](link_trait_1613) item.\n\nIf you’re sanctified to [holy](link_trait_1630) or to [unholy](link_trait_1846), you can choose to have your [relic](link_trait_3460) sanctified in the same way.","source":{"url":"https://2e.aonprd.com/Relics.aspx?ID=109","book":"Treasure Vault (Remastered)","page":"200"}}}],"dependencies":[{"table":"ability_block","queue_type":"ability-block","id":28884,"expected":{"id":28884,"name":"Telepathy","uuid":"7747103247218751","content_source_id":8,"type":"physical-feature"},"metadata":{},"metadata_absent":["deprecated","unselectable","hidden"]},{"table":"ability_block","queue_type":"ability-block","id":21081,"expected":{"id":21081,"name":"Hearing","uuid":"7294419213926000","content_source_id":3,"type":"sense"},"metadata":{"unselectable":true},"metadata_absent":["deprecated","hidden"]},{"table":"ability_block","queue_type":"ability-block","id":20776,"expected":{"id":20776,"name":"Normal Vision","uuid":"423202486919968","content_source_id":3,"type":"sense"},"metadata":{"unselectable":true},"metadata_absent":["deprecated","hidden"]},{"table":"ability_block","queue_type":"ability-block","id":22493,"expected":{"id":22493,"name":"Cathartic Mage Dedication","uuid":"3294312627250973","content_source_id":13,"type":"feat"},"metadata":{},"metadata_absent":["deprecated","unselectable","hidden"]},{"table":"trait","queue_type":"trait","id":1432,"expected":{"id":1432,"name":"Concentrate","uuid":"3011511166869167","content_source_id":3},"metadata":{},"metadata_absent":["deprecated","unselectable","hidden"]},{"table":"trait","queue_type":"trait","id":1613,"expected":{"id":1613,"name":"Intelligent","uuid":"6224381249579276","content_source_id":3},"metadata":{},"metadata_absent":["deprecated","unselectable","hidden"]},{"table":"trait","queue_type":"trait","id":1433,"expected":{"id":1433,"name":"Manipulate","uuid":"2971108648217689","content_source_id":3},"metadata":{"unselectable":false},"metadata_absent":["deprecated","hidden"]},{"table":"trait","queue_type":"trait","id":1630,"expected":{"id":1630,"name":"Holy","uuid":"4298428703725190","content_source_id":3},"metadata":{"unselectable":false},"metadata_absent":["deprecated","hidden"]},{"table":"trait","queue_type":"trait","id":1486,"expected":{"id":1486,"name":"Emotion","uuid":"3036864546165598","content_source_id":3},"metadata":{"unselectable":false},"metadata_absent":["deprecated","hidden"]},{"table":"trait","queue_type":"trait","id":1448,"expected":{"id":1448,"name":"Mental","uuid":"3793398752936386","content_source_id":3},"metadata":{"unselectable":false},"metadata_absent":["deprecated","hidden"]},{"table":"trait","queue_type":"trait","id":3460,"expected":{"id":3460,"name":"Relic","uuid":"2735161210254535","content_source_id":7},"metadata":{"unselectable":false},"metadata_absent":["deprecated","hidden"]},{"table":"trait","queue_type":"trait","id":3489,"expected":{"id":3489,"name":"Aspect Emotion","uuid":"4222561294876350","content_source_id":16},"metadata":{"unselectable":false},"metadata_absent":["deprecated","hidden"]},{"table":"trait","queue_type":"trait","id":3501,"expected":{"id":3501,"name":"Aspect Time","uuid":"4920206426614602","content_source_id":16},"metadata":{"unselectable":false},"metadata_absent":["deprecated","hidden"]},{"table":"trait","queue_type":"trait","id":1846,"expected":{"id":1846,"name":"Unholy","uuid":"6117148032754070","content_source_id":3},"metadata":{"unselectable":false},"metadata_absent":["deprecated","hidden"]},{"table":"trait","queue_type":"trait","id":3479,"expected":{"id":3479,"name":"Minor Gift","uuid":"1932552509696843","content_source_id":7},"metadata":{"unselectable":false},"metadata_absent":["deprecated","hidden"]},{"table":"trait","queue_type":"trait","id":3493,"expected":{"id":3493,"name":"Aspect Intelligent Relic","uuid":"1901020094331899","content_source_id":16},"metadata":{"unselectable":false},"metadata_absent":["deprecated","hidden"]}],"sources":[{"id":7,"name":"GM Core","user_id":null,"is_published":true,"require_key":false,"required_content_sources":[1],"group":"pathfinder-core","deprecated":null},{"id":13,"name":"Secrets of Magic (in progress)","user_id":null,"is_published":true,"require_key":false,"required_content_sources":[11],"group":"legacy","deprecated":null},{"id":3,"name":"Common Core","user_id":null,"is_published":true,"require_key":false,"required_content_sources":[],"group":"common-core","deprecated":false},{"id":8,"name":"Monster Core","user_id":null,"is_published":true,"require_key":false,"required_content_sources":[1],"group":"pathfinder-core","deprecated":null},{"id":16,"name":"Treasure Vault","user_id":null,"is_published":true,"require_key":false,"required_content_sources":[1],"group":"pathfinder-core","deprecated":null}]}$gifts$::jsonb as spec),
blocks as(select value as patch from settings cross join lateral jsonb_array_elements(spec->'blocks')),
dependencies as(select value as dependency from settings cross join lateral jsonb_array_elements(spec->'dependencies')),
actual_dependencies as(
  select dependency,to_jsonb(t)||jsonb_build_object('uuid',t.uuid::text) as actual from dependencies left join public.trait t on t.id=(dependency->>'id')::bigint where dependency->>'table'='trait'
  union all select dependency,to_jsonb(a)||jsonb_build_object('uuid',a.uuid::text) from dependencies left join public.ability_block a on a.id=(dependency->>'id')::bigint where dependency->>'table'='ability_block'
)
select 'treasure-vault-relic-gifts'::text as id,coalesce((
  (select count(*)=3 and bool_and((a.id is not null and jsonb_typeof(a.meta_data)='object'
    and not exists(select 1 from jsonb_each(patch->'expected') e where (to_jsonb(a)||jsonb_build_object('uuid',a.uuid::text))->e.key is distinct from e.value)
    and not exists(select 1 from jsonb_each(patch->'metadata') e where a.meta_data->e.key is distinct from e.value)
    and not exists(select 1 from jsonb_array_elements_text(patch->'metadata_absent') k(key) where a.meta_data?k.key)
    and jsonb_build_object('traits',a.traits,'description',a.description,'source',a.meta_data->'source')=patch->'after') is true) from blocks left join public.ability_block a on a.id=(patch->>'id')::bigint)
  and (select count(*)=16 and bool_and((actual is not null and jsonb_typeof(actual->'meta_data')='object'
    and not exists(select 1 from jsonb_each(dependency->'expected') e where actual->e.key is distinct from e.value)
    and not exists(select 1 from jsonb_each(dependency->'metadata') e where actual#>array['meta_data',e.key] is distinct from e.value)
    and not exists(select 1 from jsonb_array_elements_text(dependency->'metadata_absent') k(key) where actual->'meta_data'?k.key)) is true) from actual_dependencies)
  and (select count(*)=5 and bool_and((s.id is not null and jsonb_typeof(s.meta_data::jsonb)='object' and not exists(select 1 from jsonb_each(source_spec) e where to_jsonb(s)->e.key is distinct from e.value)) is true)
    from settings cross join lateral jsonb_array_elements(spec->'sources') source_specs(source_spec) left join public.content_source s on s.id=(source_spec->>'id')::bigint)
  and not exists(select 1 from public.content_update u where coalesce(u.status->>'state','PENDING') not in ('APPROVED','REJECTED') and (
    (u.type='content-source' and exists(select 1 from jsonb_array_elements(spec->'sources') s where u.ref_id=(s->>'id')::bigint or u.data->>'id'=s->>'id' or u.data->>'name'=s->>'name'))
    or (u.type='ability-block' and exists(select 1 from jsonb_array_elements(spec->'blocks') p where u.ref_id=(p->>'id')::bigint or u.data->>'id'=p->>'id' or u.data->>'uuid'=p#>>'{expected,uuid}' or ((u.content_source_id=(p#>>'{expected,content_source_id}')::bigint or u.data->>'content_source_id'=p#>>'{expected,content_source_id}') and u.data->>'name'=p#>>'{expected,name}')))
    or exists(select 1 from jsonb_array_elements(spec->'dependencies') d where u.type=d->>'queue_type' and (u.ref_id=(d->>'id')::bigint or u.data->>'id'=d->>'id' or u.data->>'uuid'=d#>>'{expected,uuid}' or ((u.content_source_id=(d#>>'{expected,content_source_id}')::bigint or u.data->>'content_source_id'=d#>>'{expected,content_source_id}') and u.data->>'name'=d#>>'{expected,name}')))
  ))
),false) as passed from settings
)
select original_checks.id,case when coalesce((status.value->>'recognized')::boolean,true) then coalesce((status.value->>'passed')::boolean,false) else original_checks.passed end as passed from original_checks cross join terminal_status status;
